    "ops": [
      {"action": "confirm", "category": "security", "platform": "web", "qa_ref": "qa-004", "serves_goals": ["G1", "G2"]}
    ]
  },
  {
    "qa_id": "qa-005",
    "question": "infrastructure カテゴリの web platform の仕様は？",
    "answer": "常駐ミドルウェアなし。1 コマンド起動、データはファイル 1 個。バックアップはそのファイルのコピー。",
    "ops": [
      {"action": "confirm", "category": "infrastructure", "platform": "web", "qa_ref": "qa-005", "serves_goals": ["G1", "G4"]}
    ]
  }
]
FEOF

