python3 - <<'PYEOF'
import json
from pathlib import Path

STATE_PATH = "/Users/dm/dev/dev/個人開発/HarnessHub/.worktrees/task-20260728-082322-wt-11/eval-log/dev-graph/live-trial-fixtures/system-spec-lp36-merged-r2/system-spec/spec-state.json"
data = json.loads(Path(STATE_PATH).read_text(encoding="utf-8"))

CANONICAL_PLATFORMS = ["web", "mobile", "tablet", "desktop-windows", "desktop-linux", "desktop-macos"]
PLACEHOLDER_PATTERNS = {"-", "n/a", "対象外", "N/A", ""}

cats = [c["id"] for c in data["categories"]]
matrix = data["matrix"]
qa_ids  = {e["id"] for e in data.get("qa_log", []) if isinstance(e, dict) and e.get("id")}
appr_ids = {e["id"] for e in data.get("approval_log", []) if isinstance(e, dict) and e.get("id")}
ref_ids = qa_ids | appr_ids
cat_agg = data.get("category_aggregate", {})

print("=== 軸(a): 未収集セル検出 ===")
unresolved_cells = []
for cat in cats:
    row = matrix.get(cat, {})
    for pf in CANONICAL_PLATFORMS:
        cell = row.get(pf, {})
        if isinstance(cell, dict) and cell.get("state") == "未収集":
            unresolved_cells.append((cat, pf))
if unresolved_cells:
    for c, p in unresolved_cells:
        print(f"  未収集残存: {c}.{p}")
else:
    print("  未収集セル: 0件 (全セル解決済み)")

print()
print("=== 軸(b): 対象外 reason 具体性検査 ===")
placeholder_cells = []
reason_ok_cells = []
for cat in cats:
    row = matrix.get(cat, {})
    for pf in CANONICAL_PLATFORMS:
        cell = row.get(pf, {})
        if isinstance(cell, dict) and cell.get("state") == "対象外":
            reason = cell.get("reason", "")
            apref  = cell.get("approval_ref", "")
            reason_stripped = (reason or "").strip()
            # placeholder check: 空/記号のみ/同語反復/n/a/-
            is_placeholder = (
                reason_stripped == "" or
                reason_stripped.lower() in {"n/a", "-", "na"} or
                reason_stripped == "対象外"
            )
            if is_placeholder and not (apref and apref in appr_ids):
                placeholder_cells.append((cat, pf, reason_stripped, apref))
            else:
                reason_ok_cells.append((cat, pf, reason_stripped[:60]))

if placeholder_cells:
    for c, p, r, a in placeholder_cells:
        print(f"  理由要改善: {c}.{p} reason={r!r} approval_ref={a!r}")
else:
    print(f"  対象外理由: 全{len(reason_ok_cells)}セル OK (reason 具体的 または approval_ref 解決済み)")

print()
print("=== 軸(c): 確定 qa_ref トレーサビリティ ===")
qa_log_map = {e["id"]: e for e in data.get("qa_log", []) if isinstance(e, dict) and e.get("id")}
dangling_cells = []
mismatched_cells = []
traced_ok = []
for cat in cats:
    row = matrix.get(cat, {})
    for pf in CANONICAL_PLATFORMS:
        cell = row.get(pf, {})
        if isinstance(cell, dict) and cell.get("state") == "確定":
            qa_ref = cell.get("qa_ref", "")
            if not qa_ref:
                dangling_cells.append((cat, pf, "qa_ref 欠落"))
            elif qa_ref not in ref_ids:
                dangling_cells.append((cat, pf, f"dangling: {qa_ref!r} が qa_log/approval_log に不在"))
            else:
                # 意味層: qa_log の question が当該カテゴリ×プラットフォームを指しているか
                entry = qa_log_map.get(qa_ref)
                if entry:
                    q = entry.get("question", "")
                    a = entry.get("answer", "")
                    # カテゴリ名とプラットフォーム名がqaエントリに含まれているか緩くチェック
                    cat_ok = cat in q
                    pf_ok = pf in q
                    if cat_ok and pf_ok:
                        traced_ok.append((cat, pf, qa_ref))
                    else:
                        mismatched_cells.append((cat, pf, qa_ref, q[:80]))
                else:
                    traced_ok.append((cat, pf, qa_ref))  # approval_log で解決済み

if dangling_cells:
    for c, p, note in dangling_cells:
        print(f"  qa_ref 要確認: {c}.{p} -> {note}")
if mismatched_cells:
    for c, p, ref, q in mismatched_cells:
        print(f"  qa_ref 取り違え疑い: {c}.{p} qa_ref={ref!r} question={q!r}")
if not dangling_cells and not mismatched_cells:
    print(f"  確定 qa_ref: 全{len(traced_ok)}セル OK (qa_log entry に存在・当該セル対応)")

print()
print("=== 軸(d): category_aggregate 真理値表整合 ===")

def derive_aggregate(cells):
    if all(c == "未収集" for c in cells):
        return "未着手"
    if all(c == "対象外" for c in cells):
        return "対象外"
    if any(c == "未収集" for c in cells):
        return "収集中"
    return "確定"

agg_mismatches = []
agg_missing = []
for cat in cats:
    row = matrix.get(cat, {})
    cells = [row[pf]["state"] for pf in CANONICAL_PLATFORMS if pf in row and isinstance(row[pf], dict) and "state" in row[pf]]
    derived = derive_aggregate(cells)
    declared = cat_agg.get(cat)
    if declared is None:
        agg_missing.append(cat)
    elif declared != derived:
        agg_mismatches.append((cat, declared, derived))
    # else OK

if agg_mismatches:
    for c, decl, deriv in agg_mismatches:
        print(f"  集約不一致: {c} category_aggregate={decl!r} 真理値表導出={deriv!r}")
elif agg_missing:
    for c in agg_missing:
        print(f"  宣言欠落: {c} が category_aggregate に存在しない")
else:
    print(f"  category_aggregate: 全{len(cats)}カテゴリ OK (真理値表一致・宣言欠落なし)")

print()
print("=== 軸(e): canonical platform 行の全存在 ===")
missing_pf = []
for cat in cats:
    row = matrix.get(cat, {})
    for pf in CANONICAL_PLATFORMS:
        if pf not in row:
            missing_pf.append((cat, pf))
if missing_pf:
    for c, p in missing_pf:
        print(f"  platform 欠落: {c}.{p}")
else:
    print(f"  platform 行: 全{len(cats)*6}セル存在 (欠落なし)")

print()
print("=== サマリ統計 ===")
total = 0
cnt_kakutei = 0
cnt_taishogai = 0
cnt_mishushu = 0
for cat in cats:
    row = matrix.get(cat, {})
    for pf in CANONICAL_PLATFORMS:
        cell = row.get(pf, {})
        if not isinstance(cell, dict):
            continue
        s = cell.get("state")
        total += 1
        if s == "確定": cnt_kakutei += 1
        elif s == "対象外": cnt_taishogai += 1
        elif s == "未収集": cnt_mishushu += 1

print(f"  カテゴリ数: {len(cats)}")
print(f"  セル総数: {total} (期待: {len(cats)*6})")
print(f"  確定: {cnt_kakutei}")
print(f"  対象外: {cnt_taishogai}")
print(f"  未収集: {cnt_mishushu}")
print(f"  platform 欠落数: {len(missing_pf)}")
print(f"  集約不一致: {len(agg_mismatches)} / 宣言欠落: {len(agg_missing)}")
print(f"  qa_ref dangling/取り違え: {len(dangling_cells)} / {len(mismatched_cells)}")
print(f"  対象外 理由要改善: {len(placeholder_cells)}")
PYEOF

