  1→{
  2→  "$schema": "https://json-schema.org/draft-07/schema#",
  3→  "$id": "https://harness.local/system-spec-harness/completeness-findings.schema.json",
  4→  "title": "system-spec completeness evaluation report (C05)",
  5→  "description": "生成された仕様書ドキュメントセットの完成度評価レポート。上位概念・意思決定・網羅性・deep knowledge・鮮度・prompt品質の観点 + 総合判定をfail-closedに再導出し、独立auditor帰属を実fork証跡へ接地させる。",
  6→  "type": "object",
  7→  "additionalProperties": false,
  8→  "required": ["evaluator", "verdict", "aspects", "audit_delegations", "findings", "gaps"],
  9→  "properties": {
 10→    "evaluator": {
 11→      "type": "object",
 12→      "additionalProperties": false,
 13→      "required": ["name", "version", "context"],
 14→      "properties": {
 15→        "name": {"const": "assign-system-spec-completeness-evaluator"},
 16→        "version": {"type": "string", "minLength": 1},
 17→        "context": {"const": "fork"}
 18→      }
 19→    },
 20→    "spec_dir": {"type": "string"},
 21→    "verdict": {"type": "string", "enum": ["PASS", "FAIL"]},
 22→    "aspects": {
 23→      "type": "object",
 24→      "additionalProperties": false,
 25→      "required": ["foundation_trace", "decision_guidance", "matrix_coverage", "design_knowledge_reflection", "doc_freshness", "prompt_quality"],
 26→      "properties": {
 27→        "foundation_trace": {"$ref": "#/definitions/aspect"},
 28→        "decision_guidance": {"$ref": "#/definitions/aspect"},
 29→        "matrix_coverage": {"$ref": "#/definitions/aspect"},
 30→        "design_knowledge_reflection": {"$ref": "#/definitions/aspect"},
 31→        "doc_freshness": {"$ref": "#/definitions/aspect"},
 32→        "prompt_quality": {"$ref": "#/definitions/aspect"}
 33→      }
 34→    },
 35→    "audit_delegations": {
 36→      "type": "array",
 37→      "description": "独立 context (Task fork) で起動した監査 sub-agent の receipt 一覧。auditor が C05 自身でない観点 (primary) と、宣言された sub-input 監査 (matrix_coverage の C06) に 1 件ずつ必須。PostToolUse hook が書く fork 台帳と突合され、裏取りできない帰属は fail-closed で violation になる。",
 38→      "items": {"$ref": "#/definitions/audit_delegation"}
 39→    },
 40→    "gate_results": {
 41→      "type": "array",
 42→      "items": {"$ref": "#/definitions/gate_result"}
 43→    },
 44→    "findings": {
 45→      "type": "array",
 46→      "minItems": 1,
 47→      "items": {"$ref": "#/definitions/finding"}
 48→    },
 49→    "gaps": {
 50→      "type": "array",
 51→      "items": {"type": "string", "minLength": 1},
 52→      "description": "不足事項一覧。verdict=FAIL のとき非空 (elicit/doc-fetch/compile への差し戻し材料)。"
 53→    }
 54→  },
 55→  "definitions": {
 56→    "aspect": {
 57→      "type": "object",
 58→      "additionalProperties": false,
 59→      "required": ["verdict", "auditor", "component", "summary"],
 60→      "properties": {
 61→        "verdict": {"type": "string", "enum": ["PASS", "FAIL", "INDETERMINATE"]},
 62→        "score": {"type": "number", "minimum": 0, "maximum": 100},
 63→        "auditor": {"type": "string", "minLength": 1},
 64→        "component": {"type": "string", "minLength": 1},
 65→        "summary": {"type": "string", "minLength": 1},
 66→        "evidence": {"type": "array", "items": {"type": "string"}}
 67→      }
 68→    },
 69→    "audit_delegation": {
 70→      "type": "object",
 71→      "additionalProperties": false,
 72→      "required": ["aspect", "role", "auditor", "component", "dispatch", "verdict", "evidence"],
 73→      "properties": {
 74→        "aspect": {"type": "string", "enum": ["foundation_trace", "decision_guidance", "matrix_coverage", "design_knowledge_reflection", "doc_freshness", "prompt_quality"]},
 75→        "role": {"type": "string", "enum": ["primary", "sub_input"], "description": "primary=当該観点の一次根拠 / sub_input=補助根拠 (独立観点へ昇格させない)"},
 76→        "auditor": {"type": "string", "minLength": 1, "description": "plugin 同梱の agent 定義 (agents/<auditor>.md) に実在する名前"},
 77→        "component": {"type": "string", "minLength": 1},
 78→        "dispatch": {
 79→          "type": "object",
 80→          "additionalProperties": false,
 81→          "required": ["tool", "subagent_type", "session_id"],
 82→          "properties": {
 83→            "tool": {"enum": ["Task", "Agent"], "description": "subagent 起動ツール名の観測値 (旧ハーネス/Codex 系='Task', 現行 Claude Code='Agent')。aggregate-completeness.py の LEDGER_TOOL_NAMES と整合"},
 84→            "subagent_type": {"type": "string", "minLength": 1, "description": "auditor と一致すること。fork 台帳の subagent_type と突合される"},
 85→            "session_id": {"type": "string", "minLength": 1, "description": "fork を起動した評価 session の id。宣言単独では自己申告のため、fork 台帳 (hook が harness 観測値を記録) に同一 (session_id, subagent_type) の行が実在するときだけ裏取り成立 (issue: HarnessHub-x4o)。必須 receipt 全件で同一 session を名指しすること (単一 run 収束)"}
 86→          }
 87→        },
 88→        "verdict": {"type": "string", "enum": ["PASS", "FAIL", "INDETERMINATE"], "description": "role=primary のとき aspects[aspect].verdict と一致必須 (監査判定の忠実転記)"},
 89→        "evidence": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 1}}
 90→      }
 91→    },
 92→    "gate_result": {
 93→      "type": "object",
 94→      "additionalProperties": false,
 95→      "required": ["id", "name", "exit_code"],
 96→      "properties": {
 97→        "id": {"type": "string", "minLength": 1},
 98→        "name": {"type": "string", "minLength": 1},
 99→        "conditions": {"type": "array", "items": {"type": "string"}},
100→        "command": {"type": "array", "items": {"type": "string"}},
101→        "exit_code": {"type": "integer"},
102→        "stdout": {"type": "string"},
103→        "stderr": {"type": "string"}
104→      }
105→    },
106→    "finding": {
107→      "type": "object",
108→      "additionalProperties": false,
109→      "required": ["severity", "bucket", "observation"],
110→      "properties": {
111→        "severity": {"type": "string", "enum": ["high", "medium", "low", "info"]},
112→        "bucket": {"type": "string", "minLength": 1},
113→        "observation": {"type": "string", "minLength": 1},
114→        "suggested_fix": {"type": "string"},
115→        "evidence": {"type": "array", "items": {"type": "string"}}
116→      }
117→    }
118→  }
119→}
